<?php $c = app()->make('App\Http\Controllers\Api\SponsorshipSyncController'); $all_ids = []; for ($i = 1; $i <= 10; $i++) { $req = Request::create('/api/mobile/sync/full', 'GET', ['page' => $i, 'per_page' => 100]); $res = $c->getFullSync($req)->getData()->data; foreach($res as $r) { $all_ids[] = $r->id; } } $unique_ids = array_unique($all_ids); echo 'Total fetched: ' . count($all_ids) . ', Unique: ' . count($unique_ids);
